actions.script:
const [siteId, contactListId] = String(scope).split('|')
const call = (verb, input) => ec.service.sync().name('mantle.forum.ModerationServices.' + verb).parameters({input}).call()?.result || {}
const list = Array.from(call('find#Reviews', {siteId, ...(contactListId ? {contactListId} : {}), limit: 50}).reviewList || [])
reviewList = list.map((r) => {
    let title = r.targetType === 'account' ? 'Membership request' : r.targetType
    if (r.targetType === 'post') {
        const detail = call('get#Review', {siteId, reviewId: r.reviewId})
        title = detail.post?.title || 'Post'
    }
    return {...r, siteId, title, scope,
        createdAtText: r.createdAt == null ? '' : ec.l10n.format(new Date(Number(r.createdAt)), 'yyyy-MM-dd HH:mm')}
})

const out = ec.service.sync().name('mantle.forum.ModerationServices.get#Review').parameters({input: {siteId, reviewId}}).call()?.result || {}
review = out.review || null
post = out.post || null
// Forum timestamps remain numeric in the service contract; these display values use the viewer's time zone.
const dated = (row) => ({...row,
    createdAtText: row.createdAt == null ? '' : ec.l10n.format(new Date(Number(row.createdAt)), 'yyyy-MM-dd HH:mm')})
reportList = Array.from(out.reports || []).map(dated)
noteList = Array.from(out.notes || []).map(dated)

const out = ec.service.sync().name('mantle.forum.ModerationServices.decide#Reviews').parameters({input: {siteId,
    reviewIds: Array.from(reviewIdList).map(String), decision, reason}}).call()?.result || {}
resultList = Array.from(out.results || out.resultList || [])
